{
    // Lookup table: index i holds the bit-reversed value of byte i.
    private static readonly byte[] LookupTable = BuildLookupTable();

    private static byte[] BuildLookupTable()
    {
        var table = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            int reversed = 0;
            int val = i;
            for (int bit = 0; bit < 8; bit++)
            {
                reversed = (reversed << 1) | (val & 1);
                val >>= 1;
            }
            table[i] = (byte)reversed;
        }
        return table;
    }

